/**
 * Project screenshots, inlined as JPEG data URIs.
 *
 * Generated from the original PNGs at the repo root by the build helper; do not
 * hand-edit this file.
 *
 * Rationale: a `file://` image is a tainted cross-origin resource as far as
 * WebGL is concerned, so `THREE.TextureLoader` fails for local PNGs and the
 * project cards render as empty grey panels (the per-frame fade-in is gated on
 * the texture having loaded, so the failure is silent). A data URI is
 * same-origin by definition and can never taint, so the textures load
 * identically over `file://` and over HTTP.
 *
 * The original PNGs stay on disk: the DOM `<img>` fallback and the
 * "Inspect project" modal still reference them directly.
 */
window.PORTFOLIO_TEXTURES = {
        'ticketing.png':
            'data:image/jpeg;base64,',
        'company%20website.png':
            'data:image/jpeg;base64,',
        'https://images.unsplash.com/photo-1598488035139-bdbb2231ce04?auto=format&fit=crop&w=800&q=80':
            'data:image/jpeg;base64,',
        'Expens%20tracker.png':
            'data:image/jpeg;base64,'
};
